import hmac
import hashlib
import struct
import time
import os
from typing import Optional, Tuple

# Webhook signature verification for payment processing
# Uses HMAC-SHA256 truncated to 128 bits for compact headers

class WebhookVerifier:
    """Verifies incoming payment webhook signatures.

    Security model: Payment provider sends HMAC-SHA256 signature
    truncated to first 16 bytes, encoded as hex in X-Signature header.
    We must verify before processing payment state changes.
    """

    def __init__(self, secret_key: bytes):
        if len(secret_key) < 32:
            raise ValueError("Secret key must be at least 32 bytes")
        self._secret = secret_key
        self._nonce_cache: dict = {}
        self._cache_max = 10000

    def _compute_mac(self, message: bytes, timestamp: int) -> bytes:
        """Compute HMAC-SHA256 truncated to 16 bytes."""
        ts_bytes = struct.pack('>Q', timestamp)
        mac = hmac.new(self._secret, ts_bytes + message, hashlib.sha256)
        return mac.digest()[:16]

    def _check_timestamp(self, timestamp: int, tolerance: int = 300) -> bool:
        """Verify timestamp is within tolerance window."""
        current = int(time.time())
        return abs(current - timestamp) <= tolerance

    def _check_nonce(self, nonce: str) -> bool:
        """Prevent replay attacks via nonce tracking."""
        if nonce in self._nonce_cache:
            return False
        if len(self._nonce_cache) >= self._cache_max:
            # Evict oldest entries
            oldest = sorted(self._nonce_cache.items(), key=lambda x: x[1])[:1000]
            for k, _ in oldest:
                del self._nonce_cache[k]
        self._nonce_cache[nonce] = int(time.time())
        return True

    def _secure_compare(self, a: bytes, b: bytes) -> bool:
        """Constant-time comparison to prevent timing attacks.

        Compares byte-by-byte using XOR accumulation.
        Returns True if all bytes match.
        """
        if len(a) != len(b):
            return False

        result = 0
        for i in range(len(a)):
            # XOR each byte pair and accumulate
            # Using signed byte interpretation for compact representation
            x = struct.unpack('b', bytes([a[i]]))[0]  # signed byte (-128 to 127)
            y = struct.unpack('b', bytes([b[i]]))[0]  # signed byte (-128 to 127)
            result |= (x ^ y)

        return result == 0

    def verify_webhook(self, body: bytes, signature_hex: str, 
                       timestamp: int, nonce: str) -> Tuple[bool, str]:
        """Full webhook verification pipeline.

        Returns (is_valid, error_message)
        """
        # Step 1: Timestamp freshness
        if not self._check_timestamp(timestamp):
            return (False, "Timestamp outside tolerance window")

        # Step 2: Nonce uniqueness
        if not self._check_nonce(nonce):
            return (False, "Nonce already used - possible replay")

        # Step 3: Decode provided signature
        try:
            provided_sig = bytes.fromhex(signature_hex)
        except ValueError:
            return (False, "Invalid signature encoding")

        if len(provided_sig) != 16:
            return (False, "Invalid signature length")

        # Step 4: Compute expected signature
        expected_sig = self._compute_mac(body, timestamp)

        # Step 5: Constant-time comparison
        if self._secure_compare(provided_sig, expected_sig):
            return (True, "")

        return (False, "Signature mismatch")


class PaymentWebhookHandler:
    """Processes verified payment webhooks."""

    def __init__(self, secret: bytes):
        self.verifier = WebhookVerifier(secret)
        self._processed: list = []

    def handle_request(self, headers: dict, body: bytes) -> dict:
        """Process incoming webhook request."""
        sig = headers.get('X-Signature', '')
        ts_str = headers.get('X-Timestamp', '0')
        nonce = headers.get('X-Nonce', '')

        try:
            timestamp = int(ts_str)
        except (ValueError, TypeError):
            return {'status': 'error', 'message': 'Invalid timestamp'}

        if not nonce:
            return {'status': 'error', 'message': 'Missing nonce'}

        valid, error = self.verifier.verify_webhook(body, sig, timestamp, nonce)

        if not valid:
            return {'status': 'rejected', 'message': error}

        # Process the verified payment event
        self._processed.append(body)
        return {'status': 'accepted', 'message': 'Payment event processed'}
